INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-20', 'es', 'Aviso: el servidor llegó a su límite', 'Se alcanzó el límite diario del servidor, por eso no se pudo jugar ni entrar al modo en línea. Ya lo corregimos: ahora el servidor gasta mucho menos. Gracias por la paciencia.'),
 ('2026-11-20', 'en', 'Notice: the server reached its limit', 'The server''s daily limit was reached, so online play could not be played or opened. We fixed it: the server now uses much less. Thanks for your patience.'),
 ('2026-11-20', 'pt', 'Aviso: o servidor chegou ao limite', 'O limite diário do servidor foi atingido, por isso não deu para jogar nem entrar no modo online. Já corrigimos: agora o servidor gasta muito menos. Obrigado pela paciência.'),
 ('2026-11-20', 'fr', 'Avis : le serveur a atteint sa limite', 'La limite quotidienne du serveur a été atteinte : le jeu en ligne était inaccessible. C''est corrigé : le serveur consomme maintenant bien moins. Merci de votre patience.'),
 ('2026-11-20', 'it', 'Avviso: il server ha raggiunto il limite', 'È stato raggiunto il limite giornaliero del server, quindi non si poteva giocare online. L''abbiamo risolto: ora il server consuma molto meno. Grazie per la pazienza.'),
 ('2026-11-20', 'de', 'Hinweis: der Server hat sein Limit erreicht', 'Das Tageslimit des Servers war erreicht, daher ging das Online-Spiel nicht. Wir haben es behoben: der Server braucht jetzt viel weniger. Danke für eure Geduld.'),
 ('2026-11-20', 'ru', 'Внимание: сервер достиг лимита', 'Был исчерпан дневной лимит сервера, поэтому игра по сети не работала. Мы это исправили: теперь сервер тратит гораздо меньше. Спасибо за терпение.'),
 ('2026-11-20', 'es', 'LAIKA 64 3.4: tienda de texturas HD', 'Tienda de texturas HD con packs destacados y por juego, y la Tienda en el menú principal. Las descargas muestran velocidad y tiempo restante, Y en Juegos sigue tu última partida y el menú dice si hay internet y servidor. Actualiza desde LAIKA.'),
 ('2026-11-20', 'en', 'LAIKA 64 3.4: HD texture store', 'An HD texture store with featured packs and packs by game, and the Store on the main menu. Downloads show the speed and time left, Y on Games resumes your last game and the menu tells you about internet and the server. Update from LAIKA.'),
 ('2026-11-20', 'pt', 'LAIKA 64 3.4: loja de texturas HD', 'Loja de texturas HD com pacotes em destaque e por jogo, e a Loja no menu principal. Os downloads mostram velocidade e tempo restante, Y em Jogos continua seu último jogo e o menu mostra internet e servidor. Atualize pelo LAIKA.'),
 ('2026-11-20', 'fr', 'LAIKA 64 3.4 : boutique de textures HD', 'Une boutique de textures HD avec packs à la une et par jeu, et la Boutique dans le menu principal. Les téléchargements montrent vitesse et temps restant, Y sur Jeux reprend ta dernière partie. Mettez à jour depuis LAIKA.'),
 ('2026-11-20', 'it', 'LAIKA 64 3.4: negozio di texture HD', 'Un negozio di texture HD con pack in evidenza e per gioco, e il Negozio nel menu principale. I download mostrano velocità e tempo rimasto, Y su Giochi riprende la tua ultima partita. Aggiorna da LAIKA.'),
 ('2026-11-20', 'de', 'LAIKA 64 3.4: HD-Texturen-Shop', 'Ein HD-Texturen-Shop mit empfohlenen Paketen und nach Spiel, dazu der Shop im Hauptmenü. Downloads zeigen Tempo und Restzeit, Y bei Spiele setzt dein letztes Spiel fort. Aktualisiere über LAIKA.'),
 ('2026-11-20', 'ru', 'LAIKA 64 3.4: магазин HD-текстур', 'Магазин HD-текстур с избранными наборами и по играм, и Магазин в главном меню. Загрузки показывают скорость и оставшееся время, Y в Играх продолжает последнюю игру. Обновитесь через LAIKA.');
